app.post('/api/save-bill', async (req, res) => {
  // Sequential Invoice Number Generator
let currentInvoiceSeq = 1;
try {
  const lastInv = await client.query("SELECT invoice_number FROM invoices ORDER BY id DESC LIMIT 1");
  if (lastInv.rows.length > 0) {
    const lastNumStr = lastInv.rows[0].invoice_number.replace(/\D/g, "");
    if (lastNumStr) currentInvoiceSeq = parseInt(lastNumStr, 10) + 1;
  }
} catch (e) {
  currentInvoiceSeq = Date.now().toString().slice(-4);
}
const invoiceNumber = 'INV-' + String(currentInvoiceSeq).padStart(4, '0');

  try {
    const {
      customerName,
      customerPhone,
      subtotal,
      discountAmount,
      discount,
      grandTotal,
      paymentMode,
      items
    } = req.body;

    const cName = customerName || 'Valued Customer';
    const cPhone = customerPhone || '';
    const sTotal = Number(subtotal) || 0;
    // Discount value ko dono keys se check karke read karna
    const dAmt = Number(discountAmount !== undefined ? discountAmount : discount) || 0;
    const gTotal = Number(grandTotal) || (sTotal - dAmt);
    const pMode = paymentMode || 'CASH';

    const client = await pool.connect();
    try {
      await client.query('BEGIN');

      const invRes = await client.query(
        `INSERT INTO invoices (invoice_number, customer_name, customer_phone, subtotal, discount, grand_total, payment_mode, created_at)
         VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())
         RETURNING id`,
        [invoiceNumber, cName, cPhone, sTotal, dAmt, gTotal, pMode]
      );

      const invoiceId = invRes.rows[0]?.id;

      if (invoiceId && items && items.length > 0) {
        for (const item of items) {
          try {
            await client.query(
              `INSERT INTO invoice_items (invoice_id, item_name, stylist_name, price, qty)
               VALUES ($1, $2, $3, $4, $5)`,
              [
                invoiceId,
                item.name || item.item_name || 'Service',
                item.stylist || item.staff || 'sakshi',
                Number(item.price) || 0,
                Number(item.qty) || 1
              ]
            );
          } catch (itemErr) {
            console.log('Item insert note:', itemErr.message);
          }
        }
      }

      await client.query('COMMIT');
    } catch (dbErr) {
      await client.query('ROLLBACK');
      console.log('DB Save Error:', dbErr.message);
    } finally {
      client.release();
    }

    return res.status(200).json({
      success: true,
      invoiceNumber: invoiceNumber,
      invoice_number: invoiceNumber,
      grandTotal: gTotal,
      invoiceUrl: `https://gullible-copilot-riveting.ngrok-free.dev/invoice/${invoiceNumber}`
    });

  } catch (err) {
    console.error('Save bill error:', err);
    return res.status(500).json({ error: err.message });
  }
});

// 5. DIGITAL RECEIPT WEB PAGE (HTML VIEW)
