// 1. Saare users ko fetch karna
app.get('/api/users', async (req, res) => {
  try {
    const result = await pool.query(
      'SELECT id, username, role, name, created_at FROM users ORDER BY id ASC'
    );
    res.status(200).json(result.rows);
  } catch (err) {
    console.error('Fetch users error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// 2. Naya user create karna
app.post('/api/users', async (req, res) => {
  try {
    const { username, password, role, name } = req.body;
    if (!username || !password) {
      return res.status(400).json({ error: 'Username and password are required' });
    }

    const check = await pool.query('SELECT id FROM users WHERE username = $1', [username]);
    if (check.rows.length > 0) {
      return res.status(400).json({ error: 'Username already exists' });
    }

    const result = await pool.query(
      `INSERT INTO users (username, password, role, name)
       VALUES ($1, $2, $3, $4)
       RETURNING id, username, role, name`,
      [username, password, role || 'staff', name || username]
    );

    res.status(200).json({
      success: true,
      message: 'User created successfully',
      user: result.rows[0]
    });
  } catch (err) {
    console.error('Create user error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// 8. SALES & REVENUE REPORTS API
app.get('/api/reports', async (req, res) => {
  try {
    const stats = await pool.query(`
      SELECT 
        COUNT(*)::int as total_bills,
        COALESCE(SUM(grand_total), 0)::float as total_revenue,
        COALESCE(SUM(discount), 0)::float as total_discount
      FROM bills
    `);

    const staff = await pool.query(`
      SELECT 
        COALESCE(staff_name, 'Unassigned') as staff_name,
        COUNT(*)::int as bill_count,
        COALESCE(SUM(grand_total), 0)::float as total_revenue
      FROM bills
      GROUP BY staff_name
      ORDER BY total_revenue DESC
    `);

    res.json({
      totalBills: stats.rows[0].total_bills,
      totalRevenue: stats.rows[0].total_revenue,
      totalDiscount: stats.rows[0].total_discount,
      staffBreakdown: staff.rows
    });
  } catch (err) {
    console.error('Reports API error:', err.message);
    res.status(500).json({ error: err.message });
  }
});
